"""Share of the total amount per order."""
from orders import load_orders


def amount_shares(orders):
    """Return each order's share of the total amount, in order."""
    total = sum(x.amount for x in orders)
    return [x.amount / total for x in orders]


def stored_shares():
    """Shares for the stored orders."""
    return amount_shares(load_orders())


def top_share(orders):
    """Return the largest share, or 0.0 when there are no orders."""
    shares = amount_shares(orders)
    return max(shares) if shares else 0.0


def customer_names(orders):
    """Return the distinct customer values, in first-seen order."""
    names = []
    for x in orders:
        if x.customer not in names:
            names.append(x.customer)
    return names


def describe_order(order):
    """Return a one-line description of a order."""
    return "%s: %s" % (order.customer, order.amount)

